\section{Introduction}

Additive questions about thin sequences, such as which integers are sums of two squares, of two cubes, or of two triangular numbers, are among the oldest in number theory.
In this paper we consider a quadratic sequence whose pairwise sums turn out to be governed by Fermat's two-squares theorem.

\begin{definition}[Anti-Fibonacci numbers]
For $n\ge0$ let $A_n=\frac{n(n+1)}{2}+1$.
Equivalently, $A_0=1$ and $A_n=A_{n-1}+n$ for $n\ge1$.
The sequence begins $1,2,4,7,11,16,22,29,37,46,56,67,\dots$.
Where the Fibonacci recurrence adds the previous term, this one adds the index, so the sequence grows quadratically instead of exponentially.
\end{definition}

\begin{definition}[Representable integers]
An integer $m\ge0$ is \emph{representable} if there exist $a,b\ge0$ with $m=A_a+A_b$.
Write $\R$ for the set of representable integers. For $N\ge1$ put
\[
R(N)=\#\{m\le N: m\in\R\},\qquad R^{<}(N)=\#\{0\le m<N: m\in\R\}.
\]
These differ by at most $1$.
\end{definition}

The representable integers up to $40$ are
\[
2,3,4,5,6,8,9,11,12,13,14,15,17,18,20,22,23,24,26,27,29,30,31,32,33,36,38,39,40.
\]
At $N=10^6$ about $40\%$ of all integers are representable, and this suggests positive density.
We show that this impression is wrong, and we identify the correct order of magnitude.

\subsection*{Summary of results}
\begin{enumerate}
\item \textbf{Reduction} (Theorem~\ref{thm:reduction}): $m\in\R\iff 8m-14=x^2+y^2$ for some $x,y\in\Z$ $\iff$ $m\ge2$ and $4m-7=x^2+y^2$ for some $x,y\in\Z_{\ge0}$.
\item \textbf{Fermat-type criterion} (Theorem~\ref{thm:fermat}): $m\in\R\iff m\ge2$ and $v_q(4m-7)$ is even for every prime $q\equiv3\pmod4$.
\item \textbf{Local obstruction and the $2/9$ bound} (Theorems~\ref{thm:mod9} and~\ref{thm:29}).
\item \textbf{Exact CRT sieve count} (Theorem~\ref{thm:crt}) and \textbf{sieve upper bound} (Theorem~\ref{thm:sieve}).
\item \textbf{Euler-product inequality} (Theorem~\ref{thm:euler}).
\item \textbf{Divergence of prime reciprocals in progressions} (Theorem~\ref{thm:dirichlet}).
\item \textbf{Density zero} (Theorem~\ref{thm:main}): $R(N)/N\to0$.
\item \textbf{Landau-scale asymptotic} (Theorem~\ref{thm:landau-af}): assuming Landau's classical theorem, $R(N)\sim 2b\,N/\sqrt{\log N}$, where $2b\approx1.52845$.
\end{enumerate}
Items 1--7 are proved in full from first principles, given Fermat's two-squares theorem and the standard lower bound for the Dirichlet series of the von Mangoldt function on a residue class (the analytic input to Dirichlet's theorem).
Item 8 is a short and complete deduction from Landau's 1908 theorem.

\section{The two-squares reduction}

\begin{lemma}[Basic identity]\label{lem:identity}
For every $n\ge0$, $8A_n=(2n+1)^2+7$.
\end{lemma}
\begin{proof}
$8A_n=4n(n+1)+8=(4n^2+4n+1)+7$.
\end{proof}

\begin{lemma}[Doubling]\label{lem:doubling}
For $n\in\Z_{\ge0}$, the number $2n$ is a sum of two squares of non-negative integers if and only if $n$ is.
\end{lemma}
\begin{proof}
If $n=u^2+v^2$ with $u\ge v$, then $2n=(u+v)^2+(u-v)^2$.
Conversely, if $2n=x^2+y^2$ then $x\equiv y\pmod2$.
Assuming $x\ge y$, the numbers $u=(x+y)/2$ and $v=(x-y)/2$ are non-negative integers with $u^2+v^2=(x^2+y^2)/2=n$.
\end{proof}

\begin{theorem}[Reduction to sums of two squares]\label{thm:reduction}
For every integer $m\ge0$ the following are equivalent:
\begin{enumerate}
\item $m\in\R$;
\item there are $x,y\in\Z$ with $8m-14=x^2+y^2$;
\item $m\ge2$ and there are $x,y\in\Z_{\ge0}$ with $8m-14=x^2+y^2$;
\item $m\ge2$ and there are $x,y\in\Z_{\ge0}$ with $4m-7=x^2+y^2$.
\end{enumerate}
Moreover, if $m=A_a+A_b$ then
$8m-14=(2a+1)^2+(2b+1)^2$ and $4m-7=(a+b+1)^2+(a-b)^2$.
\end{theorem}
\begin{proof}
(1$\Rightarrow$2) If $m=A_a+A_b$, adding the two instances of Lemma~\ref{lem:identity} gives $8m-14=(2a+1)^2+(2b+1)^2$.

(2$\Rightarrow$1) Suppose $8m-14=x^2+y^2$; we may assume $x,y\ge0$.
Then $x^2+y^2\equiv2\pmod8$.
An even square is $\equiv0$ or $4\pmod 8$ and an odd square is $\equiv1\pmod8$.
The possible values of $x^2+y^2\bmod 8$ are therefore $0,4$ (both even), $1,5$ (mixed parity) and $2$ (both odd).
Hence $x=2a+1$ and $y=2b+1$ with $a,b\ge0$.
By Lemma~\ref{lem:identity}, $8m=8A_a+8A_b$, so $m=A_a+A_b$.

(2$\Leftrightarrow$3) If $8m-14=x^2+y^2\ge0$ then $m\ge2$. Absolute values handle the sign.

(3$\Leftrightarrow$4) This is Lemma~\ref{lem:doubling} applied to $n=4m-7$, since $2(4m-7)=8m-14$.

The explicit formula follows from $(u+v)^2+(u-v)^2=2(u^2+v^2)$ with $u=a+b+1$ and $v=a-b$, because then $u+v=2a+1$ and $u-v=2b+1$.
\end{proof}

\begin{theorem}[Fermat--Euler]\label{thm:fe}
A positive integer $n$ is a sum of two squares if and only if $v_q(n)$ is even for every prime $q\equiv3\pmod4$.
\end{theorem}

\begin{theorem}[Fermat-type criterion]\label{thm:fermat}
An integer $m\ge0$ is representable if and only if $m\ge2$ and, for every prime $q\equiv3\pmod4$, the exponent $v_q(4m-7)$ is even.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:reduction} and~\ref{thm:fe}, noting that $4m-7\ge1$ when $m\ge2$.
\end{proof}

\begin{example}
$4\cdot37-7=141=3\cdot47$, so $v_3=1$ and $37\notin\R$.
Also $4\cdot38-7=145=5\cdot29$, so $38\in\R$; indeed $38=A_0+A_8$ and $145=9^2+8^2$.
\end{example}

\begin{corollary}[Local obstruction]\label{cor:local}
If $q\equiv3\pmod4$ is prime, $q\mid 4m-7$ and $q^2\nmid 4m-7$, then $m\notin\R$.
\end{corollary}
\begin{proof}
If $m\le1$ there is nothing to prove.
Otherwise $4m-7\neq0$ and $v_q(4m-7)=1$ is odd, so Theorem~\ref{thm:fermat} applies.
\end{proof}

\begin{remark}\label{rem:bijection}
The map $m\mapsto 4m-7$ is a bijection from $\{m\ge2\}$ onto the positive integers $\equiv1\pmod4$.
Every odd sum of two squares is $\equiv1\pmod4$.
Hence Theorem~\ref{thm:reduction} gives a bijection between $\R\cap[0,N]$ and the odd sums of two squares in $[1,4N-7]$.
\end{remark}

\section{A fixed obstruction: the prime 3}

\begin{theorem}\label{thm:mod9}
If $m\equiv1$ or $7\pmod9$ then $m\notin\R$.
\end{theorem}
\begin{proof}
For $m\le1$ this is clear. Let $m\ge2$.
If $m\equiv1\pmod 9$ then $4m-7\equiv6\pmod9$.
If $m\equiv7\pmod 9$ then $4m-7\equiv3\pmod9$.
In both cases $3\mid4m-7$ and $9\nmid4m-7$. Apply Corollary~\ref{cor:local} with $q=3$.
\end{proof}

\begin{theorem}[The $2/9$ bound]\label{thm:29}
For every $k\ge0$, $\#\{0\le m<9k: m\notin\R\}\ge2k$.
\end{theorem}
\begin{proof}
The $2k$ integers $9j+1$ and $9j+7$ for $0\le j<k$ are distinct, lie in $[0,9k)$, and are non-representable by Theorem~\ref{thm:mod9}.
\end{proof}

So the lower density of the complement of $\R$ is at least $2/9$.
Conversely, the residues $0,2,3,4,5,6,8$ modulo $9$ all occur among representable integers.
The prime $3$ excludes no other entire residue class modulo $9$, and further progress has to come from infinitely many primes.

\section{The local sieve and its exact count}

\begin{definition}[Local condition]
For a prime $p$ and $m\in\Z_{\ge0}$, say that $m$ is \emph{locally admissible at $p$} if $p\mid 4m-7$ implies $p^2\mid4m-7$, with divisibility taken in $\Z$.
For a finite set $S$ of primes, $m$ is \emph{$S$-good} if it is locally admissible at every $p\in S$.
Put $Q_S=\prod_{p\in S}p^2$ and $C_S=\prod_{p\in S}(p^2-p+1)$.
\end{definition}

\begin{lemma}\label{lem:rep-good}
If every element of $S$ is a prime $\equiv3\pmod4$ and $m\in\R$, then $m$ is $S$-good.
\end{lemma}
\begin{proof}
This is Corollary~\ref{cor:local}.
\end{proof}

\begin{lemma}[Periodic counting]\label{lem:periodic}
If $f$ is a $Q$-periodic predicate on $\Z_{\ge0}$, then $\#\{m<Qn: f(m)\}=n\cdot\#\{m<Q: f(m)\}$.
\end{lemma}
\begin{proof}
Write $m=r+Qt$ with $r<Q$ and $t<n$, and use $f(r+Qt)\iff f(r)$.
\end{proof}

\begin{lemma}[Local count]\label{lem:localcount}
Let $p$ be an odd prime, $Q\ge1$ an integer coprime to $p$, and $r\ge0$.
Then exactly $p^2-p+1$ of the integers $t\in[0,p^2)$ have the property that $r+Qt$ is locally admissible at $p$.
\end{lemma}
\begin{proof}
Write $4(r+Qt)-7=\alpha+\beta t$ with $\alpha=4r-7$ and $\beta=4Q$.
Since $p$ is odd and coprime to $Q$, $\beta$ is a unit modulo $p$ and modulo $p^2$.
If $\beta$ is a unit modulo $d\ge1$, the congruence $\alpha+\beta t\equiv0\pmod d$ has exactly one solution $t\in[0,d)$.
With $d=p^2$, exactly one $t\in[0,p^2)$ has $p^2\mid\alpha+\beta t$.
With $d=p$ and Lemma~\ref{lem:periodic}, exactly $p$ values $t\in[0,p^2)$ have $p\mid\alpha+\beta t$.
The inadmissible $t$, with $p$ dividing $\alpha+\beta t$ but $p^2$ not, therefore number $p-1$, and the admissible ones number $p^2-p+1$.
\end{proof}

\begin{theorem}[Exact CRT count]\label{thm:crt}
Let $S$ be a finite set of odd primes. Being $S$-good is periodic modulo $Q_S$, and
\[
\#\{0\le m<Q_S: m\text{ is $S$-good}\}=C_S=\prod_{p\in S}(p^2-p+1).
\]
\end{theorem}
\begin{proof}
Replacing $m$ by $m+p^2k$ changes $4m-7$ by $4p^2k$, which does not affect divisibility by $p$ or $p^2$; this gives periodicity.
For the count we use induction on $|S|$; the case $S=\varnothing$ is trivial.
Let $S'=S\cup\{p\}$ with $p\notin S$, and put $Q=Q_S$, so that $\gcd(p,Q)=1$ and $Q_{S'}=Qp^2$.
Each $m\in[0,Qp^2)$ is uniquely $r+Qt$ with $r<Q$ and $t<p^2$, and $r+Qt$ is $S$-good if and only if $r$ is.
Hence the number of $S'$-good $m<Qp^2$ equals
\[
\sum_{\substack{r<Q\\ r\ S\text{-good}}}\#\{t<p^2: r+Qt\text{ admissible at }p\}=C_S\,(p^2-p+1),
\]
by the induction hypothesis and Lemma~\ref{lem:localcount}.
\end{proof}

\begin{theorem}[Sieve upper bound]\label{thm:sieve}
Let $S$ be a finite set of primes $\equiv3\pmod4$. For every $N\ge0$,
\[
R^{<}(N)\le\Bigl(\Bigl\lfloor\frac{N}{Q_S}\Bigr\rfloor+1\Bigr)C_S.
\]
\end{theorem}
\begin{proof}
Let $M=Q_S(\lfloor N/Q_S\rfloor+1)\ge N$.
By Lemma~\ref{lem:rep-good}, the representable integers in $[0,N)$ are among the $S$-good integers in $[0,M)$.
By Lemma~\ref{lem:periodic} and Theorem~\ref{thm:crt}, there are exactly $(\lfloor N/Q_S\rfloor+1)C_S$ of these.
\end{proof}

For $S=\{3\},\{7\},\{3,7\},\{3,11\},\{7,11\},\{3,7,11\}$ the counts are $7,43,301,777,4773,33411$, agreeing with $C_S$ (with $Q_S=9,49,441,1089,5929,53361$).

\section{The Euler-product inequality}

\begin{theorem}\label{thm:euler}
Let $S$ be a finite set of integers $p\ge2$. Then
\[
\frac{C_S}{Q_S}=\prod_{p\in S}\Bigl(1-\frac{p-1}{p^2}\Bigr)\le\frac{1}{1+\frac12\sum_{p\in S}\frac1p}.
\]
\end{theorem}
\begin{proof}
Use induction on $|S|$; the empty case is $1\le1$.
Adding $p$ to $S$, write $y=(p-1)/p^2$ and $z=1/(2p)$, and let $s=\sum_{q\in S}1/q$.
For $p\ge2$ we have $0\le z\le y\le1$, since $z\le y\iff p^2\le2p(p-1)\iff p\ge2$.
By induction $C_S/Q_S\le 1/(1+s/2)$, so
\[
(1-y)\frac{C_S}{Q_S}\le\frac{1-z}{1+s/2}\le\frac{1}{1+s/2+z}.
\]
The last inequality is $(1-z)(1+s/2+z)\le1+s/2$, that is, $-z^2-zs/2\le0$.
Since $s/2+z=\frac12(s+1/p)$, this closes the induction.
\end{proof}

\section{Divergence of prime reciprocals in a residue class}

Dirichlet's theorem is often stated as the divergence of $\sum_{p\equiv a\ (q)}\frac{\log p}{p}$.
Since $\log p\ge1$, this is a weaker divergence statement than the one we need.
We use the following analytic input: if $a$ is a unit modulo $q$, there is a constant $C$ such that for all real $x>1$,
\begin{equation}\label{eq:lower}
\sum_{\substack{n\ge1\\ n\equiv a\ (q)}}\frac{\Lambda(n)}{n^x}\ge\frac{1}{\varphi(q)}\cdot\frac1{x-1}-C,
\end{equation}
where $\Lambda$ is the von Mangoldt function.
This follows from the simple pole of $\zeta$ at $1$ and the non-vanishing of $L(1,\chi)$ for non-principal characters $\chi$ modulo $q$.

\begin{theorem}\label{thm:dirichlet}
For every $q\ge1$ and every unit $a$ modulo $q$, $\displaystyle\sum_{p\equiv a\ (q)}\frac1p=\infty$.
In particular, for every $B$ there is a finite set $S$ of primes $p\equiv3\pmod4$ with $\sum_{p\in S}1/p>B$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $c=1/\varphi(q)$ and suppose the series converges.
Choose $P$ such that $\sum_{p\ge P,\,p\equiv a}1/p\le c/2$.
For $n\ge1$ and $x>1$, the inequality $\log n\le n^{x-1}/(x-1)$ gives $\log n/n^x\le 1/((x-1)n)$.
Split the left side of \eqref{eq:lower} into three parts: primes $p\ge P$ in the class, terms with $n<P$, and prime powers $p^k$ with $k\ge2$.
The first part is at most $\frac{c/2}{x-1}$.
The second is a finite sum bounded uniformly in $x>1$.
The third is bounded by the convergent series $\sum_{p,\,k\ge2}\log p/p^k$.
So the left side is at most $H+\frac{c/2}{x-1}$ for a constant $H$, which contradicts \eqref{eq:lower} as $x\to1^+$.
\end{proof}

\section{Density zero}

\begin{theorem}[Main theorem]\label{thm:main}
\[
\lim_{N\to\infty}\frac{R^{<}(N)}{N}=0,\qquad\text{equivalently}\qquad\lim_{N\to\infty}\frac{\#\{m<N: m\notin\R\}}{N}=1.
\]
\end{theorem}
\begin{proof}
Let $\varepsilon>0$.
By Theorem~\ref{thm:dirichlet} choose a finite set $S$ of primes $\equiv3\pmod4$ with $\sum_{p\in S}1/p>4/\varepsilon$.
By Theorem~\ref{thm:euler}, $C_S/Q_S<1/(1+2/\varepsilon)<\varepsilon/2$.
By Theorem~\ref{thm:sieve},
\[
\frac{R^{<}(N)}{N}\le\frac{(N/Q_S+1)C_S}{N}=\frac{C_S}{Q_S}+\frac{C_S}{N}<\varepsilon
\]
for all $N>2C_S/\varepsilon$.
The second form follows because the two counts add up to $N$.
\end{proof}

\begin{remark}[The concept, corrected]
The statement ``$\R$ has positive density'' is therefore false.
The correct normalisation is $N/\sqrt{\log N}$ (Section~\ref{sec:landau}), so positive density survives only in the Landau sense: $R(N)\sqrt{\log N}/N$ tends to a positive constant.
\end{remark}

\begin{remark}[What the elementary sieve gives quantitatively]
The error term in Theorem~\ref{thm:sieve} forces $Q_S\lesssim N$.
With $S=\{p\le z: p\equiv3\ (4)\}$ we have $\log Q_S\approx z$, so only $z\approx\log N$ is allowed.
By Mertens' theorem in progressions, $\prod_{p\le z,\,p\equiv3\,(4)}(1-(p-1)/p^2)\asymp(\log z)^{-1/2}$.
Optimising therefore gives at best $R(N)\ll N/\sqrt{\log\log N}$.
Reaching $N/\sqrt{\log N}$ needs a sieve with a remainder term that allows $z=N^\delta$ (Selberg's upper-bound sieve), or the Selberg--Delange method.
For example, at $N=10^6$ the sets $\{3\},\{3,7\},\{3,7,11\}$ give the bounds $777{,}784$, $682{,}668$ and $634{,}809$ for the true value $R^{<}(10^6)=399{,}341$.
Adding $19$ makes $Q_S>N$, and the bound jumps to $11{,}459{,}973$.
\end{remark}

\section{The Landau scale}\label{sec:landau}

\begin{theorem}[Landau, 1908]\label{thm:landau}
Let $B(x)=\#\{n\le x: n=u^2+v^2,\ u,v\in\Z\}$. Then
\[
B(x)\sim b\,\frac{x}{\sqrt{\log x}},\qquad b=\frac1{\sqrt2}\prod_{p\equiv3\ (4)}\Bigl(1-\frac1{p^2}\Bigr)^{-1/2}=0.764223653\ldots
\]
\end{theorem}

\begin{theorem}[Landau-type asymptotic for anti-Fibonacci sums]\label{thm:landau-af}
Assuming Theorem~\ref{thm:landau},
\[
R(N)\sim K\frac{N}{\sqrt{\log N}},\qquad K=2b=1.528447\ldots
\]
\end{theorem}
\begin{proof}
Let $B_{\mathrm{odd}}(x)$ count the odd $n\le x$ that are sums of two squares.
By Lemma~\ref{lem:doubling}, $n\mapsto2n$ is a bijection from sums of two squares $\le x/2$ onto even sums of two squares $\le x$.
Hence $B(x)=B_{\mathrm{odd}}(x)+B(x/2)$ exactly, and so $B_{\mathrm{odd}}(x)\sim\frac b2\,x/\sqrt{\log x}$.
By Remark~\ref{rem:bijection}, $R(N)=B_{\mathrm{odd}}(4N-7)\sim\frac b2\cdot 4N/\sqrt{\log 4N}\sim 2bN/\sqrt{\log N}$.
\end{proof}

