from __future__ import annotations

import math
from typing import Dict, Optional, Tuple


def factorize(n: int) -> Dict[int, int]:
    f: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f


def anti_fib(n: int) -> int:
    return n * (n + 1) // 2 + 1


def is_representable(m: int) -> bool:
    """Fermat-type criterion: m >= 2 and v_q(4m-7) even for all primes q = 3 mod 4."""
    if m < 2:
        return False
    return all(e % 2 == 0 for q, e in factorize(4 * m - 7).items() if q % 4 == 3)


def find_representation(m: int) -> Optional[Tuple[int, int]]:
    """Return (a, b) with m = A_a + A_b, using 4m - 7 = u^2 + v^2, a = (u+v-1)/2, b = (u-v-1)/2."""
    if not is_representable(m):
        return None
    n = 4 * m - 7
    v = 0
    while 2 * v * v <= n:
        u2 = n - v * v
        u = math.isqrt(u2)
        if u * u == u2 and u > v:
            a, b = (u + v - 1) // 2, (u - v - 1) // 2
            assert anti_fib(a) + anti_fib(b) == m
            return a, b
        v += 1
    raise AssertionError("criterion and search disagree")  # never happens


if __name__ == "__main__":
    for m in (37, 38, 1000, 123457):
        print(m, is_representable(m), find_representation(m))
